// LAB: Check an effective-address calculation
// Compute base+index*scale+displacement under a caller-supplied upper bound. The result is a numeric model, not a dereferenceable C++ pointer.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <cstdint>
#include <iostream>

int main() {
    const std::uint64_t base = 1000;
    const std::uint64_t index = 3;
    const std::uint64_t scale = 4;
    const std::uint64_t displacement = 8;
    const auto address = base + index * scale + displacement;
    std::cout << address << '\n';
    assert(address == 1020);
}

#include <cassert>
#include <cstddef>
#include <iostream>
#include <optional>

std::optional<std::size_t> effective(std::size_t base, std::size_t index,
    std::size_t scale, std::size_t displacement, std::size_t limit) {
    if(base > limit) return std::nullopt;
    if(scale != 0 && index > (limit-base)/scale) return std::nullopt;
    const auto partial = base+index*scale;
    if(displacement > limit-partial) return std::nullopt;
    return partial+displacement;
}

int main() {
    const auto result = effective(1000,3,4,8,2000);
    assert(result == 1020);
    assert(!effective(1000,300,4,0,2000));
    assert(!effective(1999,0,4,2,2000));
    assert(effective(10,0,4,2,20) == 12);
    std::cout << "address=" << *result << " invalid=rejected\n";
}
